import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1

    A = []
    for _ in range(n):
        row = [int(input_data[idx + j]) for j in range(m)]
        A.append(row)
        idx += m

    B = []
    for _ in range(n):
        row = [input_data[idx + j] for j in range(m)]
        B.append(row)
        idx += m

    for r in range(n):
        for c in range(m):
            if str(A[r][c]) != B[r][c]:
                print("-1")
                return

    ops = []
    for col in range(m):
        values = [(A[i][col], i) for i in range(n)]
        values.sort(key=lambda x: x[0])

        new_indices = [0] * n
        for rank, (_, orig_idx) in enumerate(values):
            new_indices[orig_idx] = rank

        if new_indices != list(range(n)):
            current_rows = [tuple(A[i]) for i in range(n)]
            sorted_rows = [current_rows[values[i][1]] for i in range(n)]

            for i in range(n):
                A[i] = list(sorted_rows[i])

            ops.append(col + 1)

            for r in range(n):
                for c in range(m):
                    if str(A[r][c]) != B[r][c]:
                        print("-1")
                        return

    print(len(ops))
    print(*(ops))

solve()
